const { email, search, listId, tagId, limit } = $.input;
const params = { limit: String(Math.min(limit || 20, 100)) };
if (email) params.email = email;
if (search) params.search = search;
if (listId) params.listid = listId;
if (tagId) params.tagid = tagId;
return { params };

const resp = $.steps.searchContacts.response || {};
const contacts = resp.contacts || [];
return {
  contacts: contacts.map(c => ({
    id: c.id,
    email: c.email,
    firstName: c.firstName,
    lastName: c.lastName,
    phone: c.phone,
    createdDate: c.cdate,
    tags: c.tags || []
  })),
  count: contacts.length,
  summary: `Found ${contacts.length} contact${contacts.length === 1 ? '' : 's'}`
};
